function canvas(e){const count=state.order.length;const visibleOrder=selectedDevice&&state.devices[selectedDevice]?[...state.order.filter(id=>id!==selectedDevice),selectedDevice]:state.order;return `<div class="canvas-toolbar"><span class="muted">Quadre i estança · ${count} equip${count===1?'':'s'} instal·lat${count===1?'':'s'}</span><div class="zoom-controls"><button class="btn" data-zoom="out" aria-label="Redueix el zoom">−</button><strong>${Math.round(zoom*100)} %</strong><button class="btn" data-zoom="in" aria-label="Amplia el zoom">+</button><button class="btn" data-zoom="fit">Ajusta</button></div></div><div class="canvas-wrap" id="board-scroll"><svg id="knx-board" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${BOARD.width} ${BOARD.height}" style="width:${Math.round(zoom*100)}%;min-width:${Math.round(1000*zoom)}px" role="group" aria-label="Plànol: col·loca equips i connecta els borns"><defs><pattern id="board-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#d5e3e7" stroke-width=".7"/></pattern><pattern id="room-brick" width="64" height="32" patternUnits="userSpaceOnUse"><rect width="64" height="32" fill="#faf6f0"/><path d="M0 0h64M0 32h64M32 0v16M0 16h64M0 16v16" fill="none" stroke="#e8e3db" stroke-width=".8"/></pattern></defs><rect width="${BOARD.width}" height="${BOARD.height}" fill="url(#board-grid)"/><rect x="15" y="18" width="${BOARD.width-30}" height="${BOARD.wallTop-32}" rx="16" fill="#eaf2f4" stroke="#b4cbd2" stroke-width="2"/><text x="34" y="52" class="board-tag">QUADRE ELÈCTRIC</text><text x="34" y="75" class="board-sub">Punt d'alimentació · proteccions · font · actuadors KNX</text><rect x="27" y="104" width="192" height="563" rx="13" fill="#e2e7e8" stroke="#9bafb7" stroke-dasharray="6 5" stroke-width="2"/><text x="46" y="129" class="board-sub">ENTRADA 230 V</text><text x="46" y="148" font-size="11" fill="#4d6571">Separada del carril DIN</text>${BOARD.dinRows.map((y,i)=>`<g><rect x="237" y="${y+54}" width="${BOARD.width-268}" height="58" rx="5" fill="#aabac1" stroke="#607782" stroke-width="2"/><rect x="246" y="${y+67}" width="${BOARD.width-284}" height="30" rx="3" fill="#7e929c"/><path d="M246 ${y+61}H${BOARD.width-38}M246 ${y+104}H${BOARD.width-38}" stroke="#eff3f4" stroke-width="4"/><text x="251" y="${y-35}" class="board-tag">CARRIL DIN ${i+1} · 35 mm</text></g>`).join('')}<rect x="15" y="${BOARD.wallTop}" width="${BOARD.width-30}" height="${BOARD.height-BOARD.wallTop-18}" rx="15" fill="url(#room-brick)" stroke="#dccdc0" stroke-width="2"/><text x="35" y="${BOARD.wallTop+30}" class="board-tag">ESTANÇA · MUNTATGE LLIURE</text><text x="35" y="${BOARD.wallTop+52}" class="board-sub">Pulsadors i punts de llum de la instal·lació</text><g id="wire-layer" class="${selectedWire>=0?'with-selection':''}">${wireMarkup()}</g><g id="drag-wire-layer">${previewWire()}</g>${visibleOrder.map(id=>unitMarkup(id,e)).join('')}${wireActionMarkup()}</svg></div>`;}
function tray(){
 const symbols={mains:'⚡',mcb:'▣',rcd:'▣',psu:'▤',button:'◉',button2:'◧',button4:'▦',act:'▥',act4:'▤',blindButton:'↕',blindAct:'⇅',shutter:'▤',lamp:'☼'};
 const item=key=>{
  const m=CATALOG[key],count=installed(state,key).length,disabled=m.single&&count>0;
  return `<div class="material-item ${disabled?'is-installed':''}" data-tray="${key}" aria-label="Model ${esc(m.title)}"><span class="material-icon">${symbols[key]||'◻'}</span><span class="material-info"><strong>${esc(m.title)}</strong><small>${esc(m.subtitle)} · ${m.mount==='din'?'DIN':m.mount==='wall'?'Paret':'Quadre'} · instal·lats: ${count}</small></span><button type="button" class="btn material-help" data-manual="${key}" aria-label="Manual de connexions de ${esc(m.title)}" title="Consulta els borns">?</button><button type="button" class="btn" data-add="${key}" ${disabled?'disabled':''}>${disabled?'Instal·lat':'Afegeix'}</button></div>`;
 };
 return `<div class="material-box"><div class="section-heading"><div><h3>Caixa de material</h3><p class="muted">Dispositius agrupats per funció. Dins de cada família, els models s'ordenen per nombre de tecles o canals. Arrossega un equip al plànol o prem «Afegeix».</p></div><span class="pill">${state.order.length} equips</span></div><div class="material-sections">${MODEL_GROUPS.map(group=>`<section class="material-section" aria-label="${esc(group.label)}"><div class="material-group-heading"><h4>${esc(group.label)}</h4><span>${esc(group.description)}</span></div><div class="material-grid">${group.models.map(item).join('')}</div></section>`).join('')}</div></div>`;
}
function statusline(e){return `<div class="statusline"><span class="pill ${e.psuPowered?'ok':'warn'}">Font: ${e.psuPowered?'230 V OK':'Sense tensió'}</span><span class="pill ${e.addressesValid?'ok':'warn'}">Adreces: ${e.addressesValid?'OK':'Pendents'}</span><span class="pill ${e.linked?'ok':'warn'}">Grups: ${e.linked?'OK':'Pendents'}</span><span class="pill ${e.ready?'ok':'warn'}">Circuit: ${e.ready?'Preparat':'Incomplet'}</span></div>`;}
function note(){return notice?`<div class="notice ${noticeType==='error'?'error':noticeType==='success'?'success':''}" role="status">${esc(notice)}</div>`:'';}
function wiring(e){return `<section class="panel"><div class="section-heading"><div><h2>Muntatge i cablejat</h2><p class="muted">Comença amb el plànol buit. Afegeix els equips i connecta els terminals. Selecciona un equip tocant-ne la carcassa: apareixerà la paperera per retirar-lo. Clica un conductor per desconnectar-lo.</p></div></div>${statusline(e)}<div class="board-dock" role="toolbar" aria-label="Eines de muntatge"><div class="dock-mode"><button class="btn ${mode==='wire'?'active':''}" data-mode="wire">◉ Connectar cables</button><button class="btn ${mode==='move'?'active':''}" data-mode="move">✥ Moure equips</button></div><div class="dock-placement"><label for="quick-model">Equip:</label><select id="quick-model">${MODEL_GROUPS.map(group=>`<optgroup label="${esc(group.label)}">${group.models.map(key=>`<option value="${key}">${esc(CATALOG[key].title)}</option>`).join('')}</optgroup>`).join('')}</select><button class="btn primary" data-cmd="quick-add">+ Col·loca</button><button class="btn" data-cmd="toggle-tray">${materialOpen?'Amaga':'Mostra'} la caixa</button></div></div>${materialOpen?`<div id="material-drawer">${tray()}</div>`:''}${canvas(e)}<div class="help-note">${mode==='wire'?(firstPort?`Terminal inicial: <strong>${esc(ptLabel(firstPort))}</strong>. Selecciona el terminal final.`:'Arrossega d’un born a un altre o fes dos clics. Els cables són corbats i pots moure el punt de desviació de cada conductor.'):'Arrossega els equips. Els muntats en DIN s’encaixen al carril; els receptors i pulsadors queden a l’estança.'} ${selectedWire>=0&&state.wires[selectedWire]?`<strong>Conductor seleccionat:</strong> ${esc(ptLabel(state.wires[selectedWire].a))} → ${esc(ptLabel(state.wires[selectedWire].b))}. <strong>Els dos borns estan ressaltats al plànol.</strong>`:''} ${selectedDevice?`<strong>Equip seleccionat: ${esc(label(selectedDevice))}.</strong> Prem la paperera vermella al costat de l’equip per retornar-lo a la caixa de material.`:''}</div>${note()}<div class="button-row"><button class="btn" data-cmd="cancel">Cancel·la selecció</button><button class="btn" data-cmd="export">Exporta JSON</button><button class="btn" data-cmd="import">Importa projecte</button><button class="btn danger" data-cmd="reset">Reinicia</button><input id="project-file" type="file" accept="application/json,.json" hidden/></div></section><section class="panel"><details class="wires-details"><summary><strong>Conductors (${state.wires.length})</strong> · Obre la llista d'identificació</summary>${state.wires.length?`<div class="wires-list">${state.wires.map((w,i)=>`<div class="wire-item ${selectedWire===i?'is-selected':''}"><button class="wire-identify" data-wire-list="${i}"><b style="color:${wireColor(w)}">●</b> ${esc(ptLabel(w.a))} → ${esc(ptLabel(w.b))}</button><button class="btn" data-wire-remove="${i}" aria-label="Desconnecta conductor">✕</button></div>`).join('')}</div>`:'<p class="muted">No hi ha conductors.</p>'}</details></section>`;}
/** El botó PROG de Programació i el del muntatge comparteixen d.config.programLed. */
function progStation(d,st){
 const active=d.config.programLed===true;
 const powered=st.powered===true;
 return `<div class="prog-compact-block" data-prog-device="${d.id}">
   <div class="prog-action-row" role="group" aria-label="Programació de ${esc(label(d.id))}">
    <button type="button" class="prog-linked-button ${active?'is-active':''}" data-program="${d.id}" aria-pressed="${active}" aria-label="${active?'Desactiva':'Activa'} PROG de ${esc(label(d.id))}" title="El mateix botó PROG que hi ha al muntatge"><span class="prog-linked-lens" aria-hidden="true"></span><span>PROG</span></button>
    <button type="button" class="btn prog-compact-action" data-address="${d.id}">Descarrega adreça</button>
    <button type="button" class="btn prog-compact-action" data-app="${d.id}">Descarrega app</button>
   </div>
   <div class="prog-compact-status" role="status">
    <strong data-prog-indicator="${d.id}" data-state="${active?'on':'off'}">${active?'PROG activat':'PROG desactivat'}</strong>
    <span>${powered?'Estat compartit amb el botó del muntatge.':'Sense bus KNX: connecta l’alimentació per activar PROG.'}</span>
   </div>
  </div>`;
}
function configCard(d,e){
 const c=d.config,m=CATALOG[d.model],st=e.status[d.id]||{},n=channelCount(d.model),isGeneric=GENERIC_BUTTONS.has(d.model);
 const groupFields=Array.from({length:n},(_,i)=>{const obj=objectConfig(d,i),name=channelLabel(d,i),base=n===1?`${d.id}`:`${d.id}.ch${i}`;
  const dptOptions=isGeneric?`<option value="1.001" ${obj.draft.dpt==='1.001'?'selected':''}>1.001 · Commutació ON/OFF</option><option value="1.008" ${obj.draft.dpt==='1.008'?'selected':''}>1.008 · Persiana pujar/baixar</option><option value="1.007" ${obj.draft.dpt==='1.007'?'selected':''}>1.007 · Persiana pas/aturada</option>`:d.model==='blindButton'||d.model==='blindAct'?`<option value="${esc(m.objects[i].dpt)}">${esc(m.objects[i].dpt)} · ${i===0?'Pujar / baixar':'Aturar / pas'}</option>`:`<option value="1.001" ${obj.draft.dpt==='1.001'?'selected':''}>1.001 · Commutació</option><option value="5.001" ${obj.draft.dpt==='5.001'?'selected':''}>5.001 · No compatible</option>`;
  const bitOptions=obj.draft.dpt==='1.008'?['↑ Pujar','↓ Baixar']:['Pas / atura ↑','Pas / atura ↓'];
  const valueSelect=isGeneric&&obj.draft.dpt!=='1.001'?`<label><span class="control-label">Valor enviat per ${esc(name)}</span><select class="field" data-field="${base}.value" aria-label="Valor de telegrama ${esc(name)} ${d.id}"><option value="0" ${obj.draft.value!=='1'?'selected':''}>0 · ${bitOptions[0]}</option><option value="1" ${obj.draft.value==='1'?'selected':''}>1 · ${bitOptions[1]}</option></select></label>`:'';
  const loadedInfo=obj.loaded.ga?`Carregat: ${esc(obj.loaded.ga)} · ${esc(obj.loaded.dpt)}${isGeneric&&obj.loaded.dpt!=='1.001'?` · ${esc(obj.loaded.value??'0')}`:''}`:'Sense grup carregat';
  return `<div class="channel-config"><div class="section-heading"><strong>${esc(name)}</strong><span class="pill ${obj.loaded.ga?'ok':'warn'}">${loadedInfo}</span></div><div class="config-grid"><label><span class="control-label">Adreça de grup de ${esc(name)}</span><input class="field" data-field="${base}.ga" aria-label="Adreça de grup ${esc(name)} ${d.id}" value="${esc(obj.draft.ga)}" spellcheck="false"></label><label><span class="control-label">Tipus de dada (DPT)</span><select class="field" data-field="${base}.dpt" aria-label="DPT de ${esc(name)} ${d.id}">${dptOptions}</select></label>${valueSelect}</div></div>`;
 }).join('');
 return `<div class="device-config"><div class="section-heading"><h3>${esc(m.title)} <code>${esc(d.id)}</code></h3><button type="button" class="btn material-help" data-manual="${d.model}" title="Consulta els borns" aria-label="Manual de connexions ${esc(m.title)}">?</button><span class="pill ${st.powered?'ok':'warn'}">${st.powered?'Bus alimentat':'Sense bus'}</span>${d.model==='act4'?`<span class="pill ${st.auxPowered?'ok':'warn'}">${st.auxPowered?'230 V auxiliar OK':'Sense 230 V auxiliar'}</span>`:''}</div><p class="muted">Una adreça física per equip i ${n} objecte${n>1?'s':''} de comunicació. ${isGeneric?'Cada tecla pot enviar commutació 1.001, moviment de persiana 1.008 o pas/aturada 1.007.':'Els DPT dels objectes corresponen a la funció de l’actuador.'}</p><div class="config-grid"><label><span class="control-label">Adreça física del dispositiu</span><input class="field" data-field="${d.id}.address" aria-label="Adreça física ${d.id}" value="${esc(c.draft.address)}" spellcheck="false"></label><div class="readout"><span>Carregada: <code>${esc(c.loaded.address||'—')}</code></span></div></div><div class="channel-configs">${groupFields}</div><p class="tiny muted">Els grups buits queden sense vincular. Als pulsadors, configura el valor 0/1 de pujada/baixada o pas/aturada, i descarrega l'aplicació després de qualsevol canvi. Els canvis del projecte no tenen efecte fins a la descàrrega.</p>${progStation(d,st)}</div>`;
}
function programming(e){const list=devices().filter(d=>PROGRAMMABLE.has(d.model));return `<section class="panel"><h2>Topologia i programació</h2><p class="muted">Línia 1.1 · ${list.length} dispositiu(s) programable(s). Cada equip té la seva adreça i la seva pròpia configuració carregada.</p><div class="help-note">Alimenta el bus i prem el botó vermell PROG aquí o al mateix equip del muntatge: tots dos controlen el mateix LED, que continua encès quan canvies de pestanya. Descarrega l'adreça física, defineix el grup i descarrega l'aplicació. Els canvis del projecte no funcionen fins que els descarregues.</div>${statusline(e)}${list.length?list.map(d=>configCard(d,e)).join(''):'<div class="help-note">Encara no has col·locat cap pulsador ni actuador. Torna a «Muntatge».</div>'}${note()}</section>`;}
/** Vista física: cada element apareix a les coordenades de l'estança del muntatge. */
function roomDeviceMarkup(d,e){
 const m=CATALOG[d.model],x=d.position.x,y=d.position.y-BOARD.wallTop,st=e.status[d.id]||{},n=channelCount(d.model),id=esc(d.id);
 let shape='';
 if(d.model==='shutter'){
  const pct=Math.max(0,Math.min(100,Number(st.position)||0)),h=174*pct/100;
  shape=`<rect x="7" y="12" width="238" height="210" rx="7" fill="#e7e2d9" stroke="#c3baa9" stroke-width="3"/><rect x="19" y="26" width="214" height="180" fill="#9dcee8" stroke="#fdfefe" stroke-width="10"/><rect x="29" y="36" width="194" height="160" fill="url(#room-sky)"/><path d="M126 31v170" stroke="#fcfcf7" stroke-width="8"/><rect x="29" y="34" width="194" height="${h.toFixed(2)}" class="room-shutter-blind" fill="url(#room-shutter-slat)"/><rect x="3" y="6" width="246" height="24" rx="6" fill="#cfd8db" stroke="#8b9fa7" stroke-width="1.5"/><path d="M15 16h220" stroke="#eff2f3" stroke-width="2"/><rect x="16" y="207" width="220" height="9" fill="#ded9d0"/><text class="room-shutter-label" x="126" y="239" text-anchor="middle" font-weight="750" font-size="12" fill="#2b525f">${Math.round(pct)} % tancada</text>`;
 }else if(d.model==='lamp'){
  const on=st.on===true;
  shape=`${on?`<circle cx="77" cy="64" r="64" fill="url(#room-lamp-glow)" opacity=".8"/>`:''}<path d="M55 24h44l15 39H40Z" fill="#f2eee5" stroke="#adada4" stroke-width="3"/><path d="M41 63h72" stroke="#b2aaa0" stroke-width="4"/><circle cx="77" cy="74" r="22" fill="${on?'#fff4ad':'#dbe1de'}" stroke="${on?'#efb955':'#a1aaa9'}" stroke-width="3"/><path d="M67 72q10-22 20 0L80 84h-6Z" stroke="${on?'#e1a42a':'#819299'}" fill="none" stroke-width="3"/><rect x="61" y="91" width="32" height="7" rx="3" fill="#aeb6b3"/><text x="77" y="130" text-anchor="middle" font-weight="750" font-size="12" fill="#385867">${on?'Encesa':'Apagada'}</text>`;
 }else if(d.model==='blindButton'){
  const controls=[['up','↑','Pujar'],['down','↓','Baixar']];
  shape=`<rect x="10" y="13" width="170" height="129" rx="16" fill="#f8f8f3" stroke="#babbb3" stroke-width="3"/><rect x="20" y="24" width="150" height="105" rx="10" fill="#eef0ea" stroke="#c2c8bf" stroke-width="2"/>${controls.map(([action,sign,title],i)=>`<g data-shutter="${id}:${action}" role="button" tabindex="0" aria-label="${title} amb ${esc(label(d.id))}" class="room-rocker"><rect x="${27+i*70}" y="32" width="64" height="89" rx="6" fill="url(#room-key-face)" stroke="#a9b3af" stroke-width="1.5"/><text x="${59+i*70}" y="85" text-anchor="middle" font-size="30" font-weight="750" fill="#42636e" pointer-events="none">${sign}</text></g>`).join('')}`;
 }else if(m.kind==='button'){
  const cols=n===4?2:n,rows=Math.ceil(n/cols),x0=14,y0=19,w=(m.w-28-(cols-1)*6)/cols,h=(m.h-39-(rows-1)*6)/rows;
  shape=`<rect x="5" y="7" width="${m.w-10}" height="${m.h-19}" rx="13" fill="#fafaf7" stroke="#bdc2bd" stroke-width="3"/><rect x="11" y="13" width="${m.w-22}" height="${m.h-31}" rx="9" fill="#eef1ed"/>${Array.from({length:n},(_,i)=>{const col=i%cols,row=Math.floor(i/cols),xx=x0+col*(w+6),yy=y0+row*(h+6);return `<g class="room-rocker" data-press="${id}:${i}" role="button" tabindex="0" aria-label="${esc(channelLabel(d,i))} de ${esc(label(d.id))}"><rect x="${xx}" y="${yy}" width="${w}" height="${h}" rx="5" fill="url(#room-key-face)" stroke="#b8c1bc" stroke-width="1.8"/><path d="M${xx+6} ${yy+7}H${xx+w-7}" stroke="#fff" stroke-width="2"/><text x="${xx+w/2}" y="${yy+h/2+4}" font-size="${n===1?12:10}" font-weight="750" text-anchor="middle" fill="#627983" pointer-events="none">${n===1?'◯':'ABCD'[i]}</text></g>`;}).join('')}`;
 }
 return `<g class="room-fixture" data-room-device="${id}" transform="translate(${x} ${y})" aria-label="${esc(label(d.id))}"><title>${esc(label(d.id))}</title>${shape}</g>`;
}
function roomScene(e){
 const devicesOnWall=devices().filter(d=>CATALOG[d.model].mount==='wall'),h=BOARD.height-BOARD.wallTop-18;
 return `<section class="room-scene-block"><div class="room-scene-heading"><div><h3>Estança · vista real de la instal·lació</h3><p>Els dispositius conserven l'emplaçament triat a Muntatge. La persiana es mou aquí mateix i pots accionar els pulsadors directament.</p></div><span class="pill">${devicesOnWall.length} equip${devicesOnWall.length===1?'':'s'} a l'estança</span></div><div class="room-sim-scroll"><svg id="room-sim-board" viewBox="0 0 ${BOARD.width} ${h}" xmlns="http://www.w3.org/2000/svg" role="group" aria-label="Vista de l'estança amb els equips en la posició del muntatge"><defs><linearGradient id="room-wall" x2="0" y2="1"><stop stop-color="#f9f5ed"/><stop offset="1" stop-color="#eee8dd"/></linearGradient><linearGradient id="room-key-face" x2=".2" y2="1"><stop stop-color="#fbfcf9"/><stop offset="1" stop-color="#dce2de"/></linearGradient><linearGradient id="room-sky" x2="0" y2="1"><stop stop-color="#8cc7e3"/><stop offset=".75" stop-color="#c6e6ed"/><stop offset="1" stop-color="#a8cbb0"/></linearGradient><radialGradient id="room-lamp-glow"><stop stop-color="#fff6b6" stop-opacity=".9"/><stop offset="1" stop-color="#ffe2a1" stop-opacity="0"/></radialGradient><pattern id="room-shutter-slat" width="10" height="14" patternUnits="userSpaceOnUse"><rect width="10" height="14" fill="#cdd5d8"/><path d="M0 11H10" stroke="#81979f" stroke-width="2.2"/><path d="M0 4H10" stroke="#f6f7f6" stroke-width="1.2"/></pattern></defs><rect width="${BOARD.width}" height="${h}" fill="url(#room-wall)"/><rect y="${h-33}" width="${BOARD.width}" height="33" fill="#ded2bd"/><rect y="${h-46}" width="${BOARD.width}" height="14" fill="#f9f8f3" stroke="#cfc8b9" stroke-width="2"/><path d="M0 2H${BOARD.width}" stroke="#e3dbcd" stroke-width="4"/><text x="28" y="34" font-weight="800" font-size="17" letter-spacing="1" fill="#716f65">ESTANÇA · SIMULACIÓ</text><text x="29" y="55" font-size="12" fill="#8c877b">Vista sense el cablejat · posicions conservades</text>${devicesOnWall.map(d=>roomDeviceMarkup(d,e)).join('')}${devicesOnWall.length?'':`<text x="790" y="${h/2}" text-anchor="middle" font-size="23" fill="#7f817b">Afegeix pulsadors, bombetes o persianes des del muntatge</text>`}</svg></div><p class="room-scene-note">Desplaça't horitzontalment per veure tota l'estança en pantalles petites. Per moure equips o connectar-los, torna a «01 · Muntatge».</p></section>`;
}
function simulationDeviceCard(d,e){
 const m=CATALOG[d.model],s=e.status[d.id]||{},n=channelCount(d.model);
 let details='';
 if(INPUT_MODELS.has(d.model)){
  if(d.model==='blindButton')details=`<p class="room-card-description">Grup moviment: <code>${esc(objectConfig(d,0)?.loaded.ga||'—')}</code> · Grup aturada: <code>${esc(objectConfig(d,1)?.loaded.ga||'—')}</code></p><div class="button-row"><button class="btn primary" data-shutter="${d.id}:up">↑ Pujar</button><button class="btn primary" data-shutter="${d.id}:down">↓ Baixar</button><button class="btn" data-shutter="${d.id}:stop">■ Aturar</button></div>`;
  else details=`<p class="room-card-description">Adreça física: <code>${esc(d.config.loaded.address||'—')}</code></p><div class="sim-channels">${Array.from({length:n},(_,i)=>{const cfg=objectConfig(d,i)?.loaded,action=cfg?.dpt==='1.008'?(cfg.value==='1'?'↓ Baixar':'↑ Pujar'):cfg?.dpt==='1.007'?'■ Aturar':'Prémer';return `<div class="sim-channel"><span>${esc(channelLabel(d,i))}<small>${esc(cfg?.ga||'Sense grup')} · ${esc(cfg?.dpt||'1.001')}</small></span><button class="btn primary" data-press="${d.id}:${i}">${action}</button></div>`;}).join('')}</div>`;
 }else if(OUTPUT_MODELS.has(d.model)){
  details=`<div class="sim-channels">${Array.from({length:n},(_,i)=>`<div class="sim-channel"><span>${esc(channelLabel(d,i))}<small>Grup ${esc(objectConfig(d,i)?.loaded.ga||'—')}</small></span><span class="pill ${relayState(d,i)?'ok':'warn'}">${relayState(d,i)?'Tancat':'Obert'}</span></div>`).join('')}</div>`;
 }else if(d.model==='blindAct'){
  details=`<p class="room-card-description">Contactes enclavats · fase L/COM</p><span class="pill ${s.powered?'ok':'warn'}">${s.powered?'Bus correcte':'Sense bus'}</span> <span class="pill">${d.shutterDirection==='up'?'↑ Pujada activa':d.shutterDirection==='down'?'↓ Baixada activa':'Contactes oberts'}</span>`;
 }else if(d.model==='shutter'){
  const pct=Math.round(s.position||0);
  details=`<div data-shutter-receiver="${d.id}"><div class="shutter-meta"><strong>${pct} % tancada</strong><span>${s.moving?(s.direction==='up'?'↑ Pujant':'↓ Baixant'):s.shortDirections?'Error: dos sentits actius':!s.hasPE?'Sense PE':'Aturada'}</span></div></div><label class="shutter-time">Temps de recorregut (s) <input type="number" min="5" max="60" step="1" data-travel="${d.id}" value="${d.travelSec}" aria-label="Temps de recorregut de ${esc(label(d.id))}"></label>`;
 }else if(d.model==='lamp'){
  details=`<span class="pill ${s.on?'ok':'warn'}">${s.on?'Encesa':'Apagada'}</span>${s.reversed?' <span class="pill warn">L/N invertits</span>':''}`;
 }else if(d.model==='mcb'||d.model==='rcd'){
  details=`<span class="pill ${d.protection?'ok':'warn'}">${d.protection?'Connectat':'Desconnectat'}</span><p class="room-card-description">La palanca es pot accionar a Muntatge.</p>`;
 }else if(d.model==='psu'){
  details=`<span class="pill ${e.psuPowered?'ok':'warn'}">${e.psuPowered?'30 V KNX disponibles':'Sense alimentació'}</span>`;
 }else details=`<p class="room-card-description">Origen de la xarxa 230 V · L / N / PE.</p>`;
 return `<article class="room-control-card" data-control-device="${esc(d.id)}"><header><div><strong>${esc(m.title)}</strong><small>${esc(d.id)} · ${esc(m.mount==='wall'?'Estança':m.mount==='din'?'Carril DIN':'Quadre')}</small></div><button class="btn material-help" type="button" data-manual="${esc(d.model)}" aria-label="Manual de ${esc(m.title)}">?</button></header>${details}</article>`;
}
function simulation(e){
 const functional=devices(),groups=[
  {name:'Comandaments',items:functional.filter(d=>INPUT_MODELS.has(d.model))},
  {name:'Actuadors',items:functional.filter(d=>OUTPUT_MODELS.has(d.model)||d.model==='blindAct')},
  {name:'Receptors',items:functional.filter(d=>d.model==='lamp'||d.model==='shutter')},
  {name:'Alimentació i proteccions',items:functional.filter(d=>['mains','mcb','rcd','psu'].includes(d.model))}];
 return `<section class="panel"><h2>Simulació d'una instal·lació KNX</h2><p class="muted">El plànol de l'estança reprodueix els equips on els has col·locat i mostra els receptors en funcionament. Els controls i les dades de cada dispositiu es consulten a sota. Els telegrams necessiten programació i cablejat correctes.</p>${statusline(e)}${roomScene(e)}<div class="room-control-section"><h3>Control i estat dels dispositius</h3>${groups.filter(g=>g.items.length).map(g=>`<section class="room-device-category"><h4>${g.name}</h4><div class="room-control-grid">${g.items.map(d=>simulationDeviceCard(d,e)).join('')}</div></section>`).join('')||'<p class="muted">Encara no hi ha cap dispositiu instal·lat.</p>'}</div>${note()}<div class="button-row"><button class="btn" data-tab="diagnosi">Monitor KNX →</button><button class="btn" data-tab="muntatge">Torna al muntatge</button></div></section>`;
}

function diagnostics(e){return `<section class="panel"><div class="section-heading"><h2>Diagnosi i monitor del bus</h2><button class="btn" data-cmd="clear-logs">Neteja telegrames</button></div><p class="muted">Registre didàctic de GroupValueWrite: no són captures físiques del bus TP.</p><div class="monitor-wrap"><table class="monitor"><thead><tr><th>Hora</th><th>Origen</th><th>Grup</th><th>Ordre</th><th>Servei</th><th>Actuadors receptors</th></tr></thead><tbody>${state.logs.map(l=>`<tr><td>${esc(l.time)}</td><td>${esc(l.source)} (${esc(l.sourceId)})</td><td>${esc(l.ga)}</td><td>${esc(l.value)}</td><td>${esc(l.service)}</td><td>${esc(l.dest)}</td></tr>`).join('')||'<tr><td colspan="6">Encara no hi ha telegrams.</td></tr>'}</tbody></table></div></section><section class="panel"><h2>Comprovació del projecte</h2><div class="issues">${issues(state,e).map(item=>`<div class="issue ${esc(item.severity)}">${esc(item.text)}</div>`).join('')||'<p>Sense incidències.</p>'}</div>${note()}<button class="btn primary" data-cmd="verify">Comprova el projecte</button></section>`;}
function aside(e){const program=devices().filter(d=>PROGRAMMABLE.has(d.model)),powers=devices().filter(d=>d.model==='mcb'||d.model==='rcd'),lamps=installed(state,'lamp');return `<aside><section class="panel"><h2>Proteccions</h2>${powers.length?powers.map(d=>`<div class="switch-line"><strong>${esc(label(d.id))}</strong><span class="pill ${d.protection?'ok':'warn'}">${d.protection?'Connectat':'Desconnectat'}</span></div>`).join(''):'<p class="muted">Encara no hi ha proteccions instal·lades.</p>'}<p class="tiny muted">Acciona les palanques directament sobre el quadre.</p></section><section class="panel"><h2>Estat del projecte</h2><div class="checklist">${[['Font KNX alimentada',e.psuPowered],['Adreces físiques correctes',e.addressesValid],['Objectes KNX associats',e.linked],['Càrrega controlada',e.controlledLamps.size>0||e.controlledShutters.size>0],['Proteccions no derivades',!e.bypassMcb&&!e.bypassRcd],['Projecte preparat',e.ready]].map(([t,ok])=>`<div class="check"><i class="dot ${ok?'ok':'bad'}"></i><span>${t}</span></div>`).join('')}</div><button class="btn primary" data-cmd="verify">Comprova</button></section><section class="panel"><h2>Instal·lació</h2><p class="muted">${state.order.length} equips · ${state.wires.length} conductors · ${program.length} dispositius KNX · ${lamps.length} bombetes · ${installed(state,'shutter').length} persianes.</p><div class="issues">${issues(state,e).slice(0,4).map(i=>`<div class="issue ${esc(i.severity)}">${esc(i.text)}</div>`).join('')}</div><button class="btn" data-tab="diagnosi">Diagnosi completa →</button></section></aside>`;}
function foundations(){return `<div class="learning"><section class="panel"><h2>1. Arquitectura d'una instal·lació KNX TP</h2><p>Els conductors de 230 V CA alimenten la font KNX i el circuit dels receptors. El bus KNX TP utilitza un parell propi, habitualment alimentat a uns 30 V CC, que també transporta la comunicació entre dispositius.</p><div class="help-note"><strong>Camins separats:</strong> la font alimenta el bus, els polsadors envien telegrams i els actuadors commuten els contactes del circuit de potència. La presència de bus no implica que el receptor tingui tensió.</div><h2>2. Adreces físiques</h2><p>Identifiquen una instància a la topologia: 1.1.10 i 1.1.20 són equips diferents de l'àrea 1, línia 1. El prototip treballa amb la línia 1.1 i rebutja adreces duplicades.</p><h2>3. Adreces de grup</h2><p>La direcció 1/0/1 identifica una funció compartida. Pots assignar-la a diferents pulsadors i actuadors, independentment de la seva adreça física. Cada equip ha de rebre la programació perquè la connexió lògica sigui operativa.</p><h2>4. Objectes i DPT</h2><p>Un pulsador de quatre tecles és un únic participant del bus, però disposa de quatre objectes de comunicació. Cada objecte pot tenir una adreça de grup diferent. Un actuador de quatre canals té quatre contactes independents: connecta IN1 amb OUT1, IN2 amb OUT2, IN3 amb OUT3 i IN4 amb OUT4 només quan el relé corresponent és tancat.</p><table><thead><tr><th>Element</th><th>DPT</th><th>Funció</th></tr></thead><tbody><tr><td>Pulsador genèric (1, 2 o 4 tecles)</td><td>1.001 / 1.008 / 1.007</td><td>Per tecla: commutació, moviment (0 pujar / 1 baixar) o pas/aturada</td></tr><tr><td>Actuador de relé</td><td>1.001</td><td>Rebre ordre i canviar el contacte</td></tr><tr><td>Bombeta</td><td>—</td><td>Receptor de 230 V, sense objectes KNX</td></tr></tbody></table><h2>5. Persianes KNX: ordres i cablejat</h2><p>El motor reversible de 230 V disposa de dos conductors de fase per al sentit de pujada (↑) i baixada (↓), a més de neutre N i protecció PE. L’actuador rep fase protegida al born IN i només tanca un dels contactes ↑ o ↓; els dos no s’han d’alimentar simultàniament.</p><table><thead><tr><th>Objecte</th><th>DPT</th><th>Comportament</th></tr></thead><tbody><tr><td>Moviment</td><td>1.008</td><td>0 = pujar, 1 = baixar</td></tr><tr><td>Aturar / pas</td><td>1.007</td><td>Atura el moviment actual; sense regulació de lamel·les en aquesta versió</td></tr></tbody></table><p>Els pulsadors genèrics poden controlar persianes: a Programació tria el DPT de cada tecla, selecciona el valor 0/1 i associa-la al grup corresponent de l’actuador. En aquest prototip, cada tecla genèrica envia un únic objecte; per fer pujada, baixada i aturada amb tecles diferents, se’n necessiten tres. El pulsador específic de persiana manté els seus objectes de moviment i aturada. El DPT 1.007 s’utilitza aquí per aturar el motor, sense simulació de pas de lamel·les.</p><p>El recorregut es pot configurar entre 5 i 60 segons. Els finals de carrera aturen el desplaçament als valors 0 % (oberta) i 100 % (tancada). La posició és una estimació didàctica basada en el temps, no una lectura real del motor.</p><p>El conductor PE no és una sortida del relé. Va separat cap a la carcassa del motor. La simulació impedeix moure la persiana si falta el PE o el neutre.</p><p class="muted">Aquesta versió representa el comportament didàctic del bus, no trames de baix nivell, fallades de curtcircuit reals o un sistema ETS.</p></section></div>`;}
function help(){return `<div class="learning"><section class="panel"><h2>Ajuda · LAB-013 v0.3.1</h2><details open><summary>Afegir i col·locar equips</summary><p>La caixa de material està ordenada per funció: alimentació i proteccions, comandament, actuadors i receptors. Pots afegir més d'un pulsador, actuador o lluminària amb «Afegeix» o arrossegant-los al plànol. L'origen 230 V, les dues proteccions i la font KNX són únics en aquest prototip.</p></details><details><summary>Moure, seleccionar i retirar dispositius</summary><p>Prem «Moure equips» i arrossega el cos de cada dispositiu. Els equips de carril DIN queden a una de les dues guies, els elements murals a l'estança. Selecciona un equip tocant la carcassa, amb qualsevol eina activa: apareix una paperera vermella al costat. Prem-la per tornar-lo a la caixa de material. Si té cables connectats, cal confirmar-ho i aquests cables també s'eliminaran. També pots usar la tecla Suprimir amb l'equip seleccionat.</p></details><details><summary>Connectar, identificar i eliminar cables</summary><p>Prem «Connectar cables». Arrossega d'un born fins a un altre, o selecciona dos borns consecutivament. Clica una corba per ressaltar el conductor i els dos borns on està connectat i veure el botó flotant «Desconnecta». Amb el punt circular de la corba en pots canviar el recorregut.</p></details><details><summary>Parametritzar cada pulsador i actuador</summary><p>Alimenta el bus, escriu una adreça física única, prem el botó vermell PROG i descarrega l'adreça. Després escriu l'adreça de grup i prem «Descarrega aplicació». La configuració del projecte i la carregada són independents.</p></details><details><summary>Provar més d'un dispositiu</summary><p>Prova el pulsador de dues o quatre tecles i l'actuador de quatre canals. Una única adreça física identifica tot l'equip, però cada tecla i cada canal poden utilitzar grups diferents. Assigna un grup compartit a dos pulsadors i a dos actuadors, amb les seves adreces físiques diferents. Els telegrames d'un pulsador arribaran als actuadors compatibles i alimentats. Pots connectar diversos receptors als contactes dels actuadors.</p></details><details><summary>Programar els DPT de persiana als pulsadors genèrics</summary><p>En un pulsador d’1, 2 o 4 tecles, entra a Programació. Per a cada tecla, tria 1.001 (llum), 1.008 (moviment ↑/↓) o 1.007 (pas/aturada). Per a 1.008 assigna valor 0 a pujar i valor 1 a baixar. Per a 1.007, els valors 0/1 indiquen el sentit de pas; el simulador tracta tots dos com una aturada i no simula lamel·les. Assigna el mateix grup de moviment o aturada que a l’actuador KNX de persiana i prem «Descarrega aplicació» per aplicar-lo.</p><p>Exemple amb un pulsador de quatre tecles: A = 1.008 (0, ↑), B = 1.008 (1, ↓), C = 1.007 (aturar) i D = 1.001 (llum). Les tecles no configurades no envien ordres.</p></details><details><summary>Programar diversos canals</summary><p>Descarrega una única adreça física a l'equip i després assigna les adreces de grup a les tecles o canals que vulguis utilitzar. Deixa els altres grups en blanc. Prem «Descarrega aplicació» per activar els canvis. Els borns L i N alimenten l’actuador de quatre canals i els contactes IN1/OUT1, IN2/OUT2, IN3/OUT3 i IN4/OUT4 corresponen als canals A, B, C i D.</p></details><details><summary>Manual ràpid de connexions</summary><p>Prem el botó «?» de cada dispositiu, o el «?» de la caixa de material, per veure què vol dir cada born i l'esquema recomanat. En un portalàmpades E27, connecta L al contacte central i N a la rosca exterior; la inversió pot encendre la bombeta, però no és segura. L'actuador de quatre canals té alimentació auxiliar L/N i quatre contactes IN/OUT independents.</p></details><details><summary>Instal·lar una persiana KNX</summary><p>Afegeix «Pulsador KNX · persiana», «Actuador KNX · persiana» i «Motor i persiana · 230 V». Porta la fase protegida al born IN de l’actuador; connecta ↑ amb ↑ del motor i ↓ amb ↓. Porta N des de la protecció fins al motor i PE directament des de la presa de protecció de la xarxa. Connecta +/− del bus al pulsador i a l’actuador. Prem «?» per veure els borns detallats.</p><p>Descarrega una adreça física diferent a cada dispositiu. A l’objecte de moviment DPT 1.008 assigna, per exemple, el grup 2/0/1 als dos dispositius. A l’objecte d’aturada DPT 1.007, assigna 2/0/2. Descarrega les aplicacions i prova ↑, ↓ i ■ a Simulació.</p></details><details><summary>Vista de l’estança durant la simulació</summary><p>Les persianes, els pulsadors i les bombetes es mostren a la mateixa posició de l’estança que has triat a Muntatge. A Simulació el dibuix es representa com una estança real, sense els borns ni els cables visibles. Pots accionar els pulsadors directament sobre la paret i veure com es mou la persiana o s’encén la llum. A sota tens una fitxa de control per cada dispositiu, amb l’estat, els grups KNX i el temps de recorregut quan correspon. Per moure els equips, torna a Muntatge.</p><p>El botó PROG dels equips és vermell fosc quan està apagat i vermell lluminós quan el dispositiu entra en programació.</p></details><details><summary>Guardar i recuperar</summary><p>«Exporta JSON» conserva models, instàncies, connexions, posicions, adreces i estat dels equips. «Importa projecte» admet projectes v0.2 i intenta migrar els arxius de la sèrie v0.1.</p></details><p class="muted">Limitacions: una línia TP, relés de commutació d'un i quatre canals, bus i tensions simplificats, amb una persiana motoritzada genèrica, sense posicionament KNX percentual, lamel·les ni acobladors.</p></section></div>`;}
function guideColor(port){return port.kind==='bus-p'?'#cb3d40':port.kind==='bus-m'?'#4c5860':port.kind==='ac-n'?'#2473ad':port.kind==='ac-pe'?'#608037':'#ad6630';}
function terminalManual(model){
 if(model==='index')return `<div class="manual-backdrop" data-manual-backdrop><section class="manual-dialog" role="dialog" aria-modal="true" aria-labelledby="manual-title"><header class="manual-header"><div><small>LAB-013 · Consulta ràpida</small><h2 id="manual-title">Manuals de connexions</h2></div><button type="button" class="manual-close" data-manual-close aria-label="Tanca els manuals">✕</button></header><div class="manual-content"><p>Selecciona un dispositiu per consultar els borns i el seu esquema de connexió.</p>${MODEL_GROUPS.map(group=>`<h3>${esc(group.label)}</h3><div class="guide-chooser">${group.models.map(key=>`<button type="button" class="btn" data-manual="${key}">${esc(CATALOG[key].title)} <span aria-hidden="true">›</span></button>`).join('')}</div>`).join('')}</div></section></div>`;
 const m=CATALOG[model],guide=DEVICE_GUIDES[model];if(!m||!guide)return '';
 const rows=m.ports.map(port=>`<tr><td><span class="guide-terminal" style="border-left:4px solid ${guideColor(port)}">${esc(port.name)}</span></td><td>${esc(guide.terms[port.id]||port.name)}</td></tr>`).join('');
 const diagram=model==='act4'?`<div class="guide-channels">${['A','B','C','D'].map((channel,i)=>`<div><strong>Canal ${esc(channel)}</strong><div class="guide-pair"><span>IN${i+1}</span><svg viewBox="0 0 54 32" role="img" aria-label="Contacte de relé normalment obert"><g stroke="#356776" stroke-width="2" stroke-linecap="round" fill="none"><path d="M 2 21 H 10 M 44 21 H 52"/><circle cx="12" cy="21" r="3"/><circle cx="42" cy="21" r="3"/><path d="M 15 19 L 37 11"/></g></svg><span>OUT${i+1}</span></div></div>`).join('')}</div><p class="guide-mini">Els borns <strong>IN i OUT de cada canal estan junts a la part inferior</strong>. El símbol sobre la carcassa representa un contacte de relé normalment obert. L/N alimenten el dispositiu; cada IN ha de rebre fase protegida i cada OUT la transmet quan el seu relé es tanca. El bus KNX controla els quatre relés.</p>`:model==='blindAct'?`<div class="guide-connection"><span>Fase protegida → L / COM</span><span>Sortida ↑ → motor PUJAR</span><span>Sortida ↓ → motor BAIXAR</span><span>N i PE → motor directament</span></div><div class="guide-actuator-schematic"><svg viewBox="0 0 530 144" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Esquema: fase L comuna, dos contactes de relé enclavats i sortides de pujar i baixar, alimentació de control pel bus KNX"><rect x="8" y="20" width="508" height="118" rx="9" fill="#f6fafb" stroke="#a8c5cb"/><g stroke="#346371" stroke-width="2.6" fill="none" stroke-linecap="round"><path d="M38 72H106V47H167 M106 72V107H167"/><circle cx="169" cy="47" r="3.5"/><circle cx="169" cy="107" r="3.5"/><circle cx="231" cy="47" r="3.5"/><circle cx="231" cy="107" r="3.5"/><path d="M173 44L225 32 M173 104L225 92 M235 47H337 M235 107H337"/></g><g fill="#235668" font-family="sans-serif" font-weight="700" font-size="14"><text x="18" y="64">L/COM</text><text x="351" y="52">↑ PUJAR</text><text x="351" y="112">↓ BAIXAR</text><text x="176" y="17" font-size="11">CONTACTES ENCLAVATS</text></g></svg><p>Model alimentat pel bus KNX: no requereix N auxiliar. El motor rep neutre i protecció directament.</p></div>`:model==='shutter'?`<div class="guide-connection"><span>↑ PUJAR</span><span>Sortida ↑ de l’actuador</span><span>↓ BAIXAR</span><span>Sortida ↓ de l’actuador</span><span>N (neutre)</span><span>Neutre 230 V del quadre</span><span>PE (protecció)</span><span>Conductor de protecció de terra</span></div>`:model==='lamp'?`<div class="guide-connection"><span>L · fase commutada</span><span>→ contacte central E27</span><span>N · neutre</span><span>→ rosca exterior E27</span></div>`:`<div class="guide-flow">${esc(guide.flow)}</div>`;
 return `<div class="manual-backdrop" data-manual-backdrop><section class="manual-dialog" role="dialog" aria-modal="true" aria-labelledby="manual-title" aria-describedby="manual-description"><header class="manual-header"><div><small>LAB-013 · Consulta ràpida de borns</small><h2 id="manual-title">${esc(m.title)}</h2></div><button type="button" class="manual-close" data-manual-close aria-label="Tanca el manual">✕</button></header><div class="manual-content"><p id="manual-description">${esc(guide.summary)}</p>${diagram}<div class="guide-back"><button class="btn" type="button" data-manual="index">‹ Tots els equips</button></div><h3>Funció dels terminals</h3><table class="guide-table"><thead><tr><th>Born</th><th>Connexió</th></tr></thead><tbody>${rows}</tbody></table><p class="guide-tip"><strong>Atenció:</strong> ${esc(guide.tip)}</p><p class="guide-disclaimer">Esquema didàctic del model genèric TecLab. Per a equips comercials cal seguir sempre l'esquema i la documentació del fabricant.</p></div></section></div>`;
}
function syncLabSticky(){const nav=root.querySelector('.subtabs');if(nav)root.style.setProperty('--lab-subtabs-height',`${Math.ceil(nav.getBoundingClientRect().height)+8}px`);}
window.addEventListener('resize',syncLabSticky);
function render(){const e=evaluate(state);document.querySelectorAll('[data-major]').forEach(b=>b.classList.toggle('active',b.dataset.major===section));if(section!=='laboratori'){root.innerHTML='<div class="quick-manual-inline"><button class="btn" data-manual="index">? Manuals de connexió dels dispositius</button></div>'+(section==='fonaments'?foundations():help())+(manualModel?terminalManual(manualModel):'');return;}const content=tab==='muntatge'?wiring(e):tab==='programacio'?programming(e):tab==='simulacio'?simulation(e):diagnostics(e);root.innerHTML=`<nav class="subtabs" aria-label="Espais de treball"><button data-tab="muntatge" class="${tab==='muntatge'?'active':''}">01 · Muntatge</button><button data-tab="programacio" class="${tab==='programacio'?'active':''}">02 · Programació</button><button data-tab="simulacio" class="${tab==='simulacio'?'active':''}">03 · Simulació</button><button data-tab="diagnosi" class="${tab==='diagnosi'?'active':''}">04 · Diagnosi</button><button class="quick-manual-button" data-manual="index">? Manuals de connexió</button></nav><div class="workspace"><div class="workspace-main">${content}</div>${aside(e)}</div>${manualModel?terminalManual(manualModel):''}`;root.querySelector('#knx-board')?.classList.toggle('move-mode',mode==='move');syncLabSticky();}
function coord(svg,event){const pt=svg.createSVGPoint();pt.x=event.clientX;pt.y=event.clientY;return pt.matrixTransform(svg.getScreenCTM().inverse());}
function boardAt(clientX,clientY){const board=document.querySelector('#knx-board');if(!board)return null;const r=board.getBoundingClientRect();if(clientX<r.left||clientX>r.right||clientY<r.top||clientY>r.bottom)return null;return coord(board,{clientX,clientY});}
function placeModel(model,point=null){const r=addDevice(state,model,point);if(r.ok){selectedDevice=r.id;selectedWire=-1;mode='move';}show(r.msg,r.ok?'success':'error');}
function retireDevice(id){
 const device=state.devices[id];if(!device)return;
 const connected=state.wires.filter(w=>w.a.startsWith(id+':')||w.b.startsWith(id+':')).length;
 if(connected&&!confirm(`Vols retirar ${label(id)}?\n\nS'eliminaran també ${connected} conductor${connected===1?'':'s'} connectat${connected===1?'':'s'} i la seva configuració. `))return;
 removeDevice(state,id);selectedDevice='';selectedWire=-1;firstPort='';dragging=null;
 show(`${CATALOG[device.model].title} retirat de la instal·lació${connected?` amb ${connected} conductors`:''}. Pots tornar-lo a afegir des de la caixa de material.`,'success');
}
function applyDeviceMove(ev){if(!dragging)return;const pt=coord(root.querySelector('#knx-board'),ev);const d=state.devices[dragging.id],m=CATALOG[d.model];moveDevice(state,d.id,{x:pt.x-dragging.dx+m.w/2,y:pt.y-dragging.dy+m.h/2});const g=root.querySelector(`[data-device="${d.id}"]`);if(g)g.setAttribute('transform',`translate(${d.position.x} ${d.position.y})`);const layer=root.querySelector('#wire-layer');if(layer)layer.innerHTML=wireMarkup();}
root.addEventListener('pointerdown',ev=>{
 if(section!=='laboratori'||tab!=='muntatge')return;
 const h=ev.target.closest('[data-route-handle]');if(h){const i=Number(h.dataset.routeHandle),svg=root.querySelector('#knx-board');if(!state.wires[i])return;const g=routeInfo(state.wires[i],i);routing={pointer:ev.pointerId,index:i,origin:coord(svg,ev),axis:g.axis,offset:state.wires[i].offset||0};svg.setPointerCapture(ev.pointerId);ev.preventDefault();ev.stopPropagation();return;}
 const port=ev.target.closest('[data-port]');if(port&&mode==='wire'){const svg=root.querySelector('#knx-board');wireDrag={start:port.dataset.port,pointer:ev.pointerId,point:coord(svg,ev),moved:false};svg.setPointerCapture(ev.pointerId);ev.preventDefault();return;}
 if(mode==='move'){const g=ev.target.closest('.unit');if(g&&!ev.target.closest('[data-protect],[data-program],[data-press],[data-port],[data-manual],[data-device-remove]')){const svg=root.querySelector('#knx-board'),pt=coord(svg,ev),d=state.devices[g.dataset.device];dragging={pointer:ev.pointerId,id:d.id,dx:pt.x-d.position.x,dy:pt.y-d.position.y};selectedDevice=d.id;svg.setPointerCapture(ev.pointerId);ev.preventDefault();return;}}
 const tray=ev.target.closest('[data-tray]');if(tray&&!ev.target.closest('button')){const model=tray.dataset.tray;if(CATALOG[model]?.single&&installed(state,model).length)return;trayDrag={pointer:ev.pointerId,model,x:ev.clientX,y:ev.clientY};ghost=document.createElement('div');ghost.className='material-ghost';ghost.textContent=CATALOG[model].title;document.body.append(ghost);ghost.style.transform=`translate(${ev.clientX+10}px,${ev.clientY+10}px)`;ev.preventDefault();return;}
});
root.addEventListener('pointermove',ev=>{
 if(routing&&ev.pointerId===routing.pointer){const svg=root.querySelector('#knx-board'),pt=coord(svg,ev);state.wires[routing.index].offset=Math.round(Math.max(-240,Math.min(240,routing.offset+pt[routing.axis]-routing.origin[routing.axis])));const layer=svg.querySelector('#wire-layer');if(layer)layer.innerHTML=wireMarkup();return;}
 if(wireDrag&&ev.pointerId===wireDrag.pointer){const svg=root.querySelector('#knx-board');wireDrag.point=coord(svg,ev);const a=portPoint(wireDrag.start);if(a&&Math.hypot(wireDrag.point.x-a.x,wireDrag.point.y-a.y)>12)wireDrag.moved=true;const layer=svg.querySelector('#drag-wire-layer');if(layer)layer.innerHTML=previewWire();return;}
 if(dragging&&ev.pointerId===dragging.pointer){applyDeviceMove(ev);return;}
});
root.addEventListener('pointerup',ev=>{
 if(routing&&ev.pointerId===routing.pointer){routing=null;show('Recorregut ajustat.','success');return;}
 if(wireDrag&&ev.pointerId===wireDrag.pointer){const w=wireDrag;wireDrag=null;const end=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-port]')?.dataset.port;if(w.moved){skipPortClick=true;requestAnimationFrame(()=>{skipPortClick=false;});if(end&&end!==w.start){const r=connect(state,w.start,end);selectedWire=-1;firstPort='';show(r.msg,r.ok?'success':'error');}else{firstPort='';show('El cable no s’ha connectat: selecciona un born de destí.','error');}}else if(firstPort&&firstPort!==w.start){const r=connect(state,firstPort,w.start);firstPort='';selectedWire=-1;show(r.msg,r.ok?'success':'error');}else{firstPort=firstPort===w.start?'':w.start;render();}return;}
 if(dragging&&ev.pointerId===dragging.pointer){dragging=null;show('Equip posicionat.','success');}
});
root.addEventListener('pointercancel',()=>{routing=null;wireDrag=null;dragging=null;});
document.addEventListener('pointermove',ev=>{if(trayDrag&&trayDrag.pointer===ev.pointerId&&ghost)ghost.style.transform=`translate(${ev.clientX+10}px,${ev.clientY+10}px)`;});
document.addEventListener('pointerup',ev=>{if(!trayDrag||trayDrag.pointer!==ev.pointerId)return;const {model}=trayDrag;trayDrag=null;ghost?.remove();ghost=null;const pt=boardAt(ev.clientX,ev.clientY);if(pt)placeModel(model,pt);});
root.addEventListener('click',ev=>{
 if(ev.target.matches('[data-manual-backdrop]')){manualModel='';render();return;}
 const t=ev.target.closest('[data-device-remove],[data-manual-close],[data-manual],[data-tab],[data-mode],[data-add],[data-protect],[data-program],[data-port],[data-wire-index],[data-wire-remove],[data-wire-list],[data-address],[data-app],[data-press],[data-shutter],[data-cmd],[data-zoom]');
 if(t?.hasAttribute('data-device-remove')){retireDevice(t.dataset.deviceRemove);return;}
 if(!t){const equipment=ev.target.closest('.unit[data-device]');if(equipment&&section==='laboratori'&&tab==='muntatge'){
  selectedDevice=equipment.dataset.device;selectedWire=-1;firstPort='';render();
 }else if(ev.target.closest('#knx-board')&&selectedDevice){selectedDevice='';render();}
 return;}
 if(t.hasAttribute('data-manual-close')){manualModel='';render();manualFocus?.focus();manualFocus=null;return;}
 if(t.dataset.manual){manualFocus=document.activeElement;manualModel=t.dataset.manual;render();root.querySelector('[data-manual-close]')?.focus();return;}
 if(t.dataset.tab){const changed=tab!==t.dataset.tab;tab=t.dataset.tab;selectedWire=-1;notice='';render();if(changed)root.querySelector('.subtabs')?.scrollIntoView({block:'start',behavior:'auto'});return;}
 if(t.dataset.mode){mode=t.dataset.mode;selectedWire=-1;firstPort='';render();return;}
 if(t.dataset.add){placeModel(t.dataset.add);return;}
 if(t.dataset.protect){toggleProtection(state,t.dataset.protect);show('Protecció accionada.');return;}
 if(t.dataset.program){const r=toggleProgram(state,t.dataset.program);show(r.msg,r.ok?'success':'error');return;}
 if(t.dataset.port){if(skipPortClick){skipPortClick=false;return;}if(mode!=='wire')return;const ref=t.dataset.port;if(firstPort&&firstPort!==ref){const r=connect(state,firstPort,ref);firstPort='';selectedWire=-1;show(r.msg,r.ok?'success':'error');}else {firstPort=firstPort===ref?'':ref;render();}return;}
 if(t.dataset.wireIndex!==undefined||t.dataset.wireList!==undefined){selectedDevice='';selectedWire=Number(t.dataset.wireIndex??t.dataset.wireList);render();return;}
 if(t.dataset.wireRemove!==undefined){disconnect(state,Number(t.dataset.wireRemove));selectedWire=-1;show('Conductor desconnectat.','success');return;}
 if(t.dataset.address){const r=downloadAddress(state,t.dataset.address);show(r.msg,r.ok?'success':'error');return;}
 if(t.dataset.app){const r=downloadApplication(state,t.dataset.app);show(r.msg,r.ok?'success':'error');return;}
 if(t.dataset.shutter){const [id,action]=t.dataset.shutter.split(':');const r=pressShutter(state,id,action);show(r.msg,r.ok?'success':'error');return;}
 if(t.dataset.press){const [id,ch]=t.dataset.press.split(':');const r=pressButton(state,id,Number(ch||0));show(r.msg,r.ok?'success':'error');return;}
 if(t.dataset.zoom){zoom=t.dataset.zoom==='fit'?1:t.dataset.zoom==='in'?Math.min(2,zoom+.15):Math.max(.65,zoom-.15);render();return;}
 const cmd=t.dataset.cmd;if(!cmd)return;
 if(cmd==='toggle-tray'){materialOpen=!materialOpen;render();}
 else if(cmd==='quick-add'){placeModel(root.querySelector('#quick-model')?.value||'button');}
 else if(cmd==='cancel'){firstPort='';selectedWire=-1;selectedDevice='';render();}
 else if(cmd==='remove-device'){if(selectedDevice)retireDevice(selectedDevice);}
 else if(cmd==='verify'){const e=evaluate(state),i=issues(state,e);show(e.ready?'Instal·lació preparada per a la prova funcional.':i[0]?.text||'Revisa el projecte.',e.ready?'success':'error');}
 else if(cmd==='clear-logs'){state.logs=[];show('Monitor netejat.');}
 else if(cmd==='reset'){if(confirm('Reiniciar tot el projecte, retirant dispositius, cablejat i programació?')){state=createProject();selectedWire=-1;selectedDevice='';firstPort='';materialOpen=true;mode='wire';show('Projecte nou i buit.');}}
 else if(cmd==='export'){const data=JSON.stringify(saveProject(state),null,2),url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='TecLab-KNX-LAB-013-projecte-v0.3.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);show('Projecte exportat a JSON.','success');}
 else if(cmd==='import'){root.querySelector('#project-file')?.click();}
});
root.addEventListener('input',ev=>{const f=ev.target.dataset?.field;if(ev.target.hasAttribute('data-travel')){const d=state.devices[ev.target.dataset.travel];if(d?.model==='shutter'){const v=Number(ev.target.value);if(Number.isFinite(v)&&v>=5&&v<=60)d.travelSec=v;}return;}if(!f)return;const [id,key,property]=f.split('.'),d=state.devices[id];if(!d?.config)return;if(key?.startsWith('ch')&&['ga','dpt','value'].includes(property)){const cfg=objectConfig(d,Number(key.slice(2)));if(cfg)cfg.draft[property]=ev.target.value;}else if(['address','ga','dpt','value'].includes(key))d.config.draft[key]=ev.target.value;if((property==='dpt'||key==='dpt')&&GENERIC_BUTTONS.has(d.model))render();});
root.addEventListener('change',async ev=>{if(ev.target.id!=='project-file')return;const file=ev.target.files?.[0];if(!file)return;try{state=loadProject(JSON.parse(await file.text()));selectedDevice='';selectedWire=-1;firstPort='';mode='wire';show('Projecte importat. Comprova les connexions i les adreces.','success');}catch(error){show('No es pot importar el projecte: '+error.message,'error');}});
root.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&manualModel){manualModel='';render();manualFocus?.focus();manualFocus=null;ev.preventDefault();return;} if((ev.key==='Delete'||ev.key==='Backspace')&&!ev.target.closest('input,textarea,select')){
 if(selectedWire>=0){ev.preventDefault();disconnect(state,selectedWire);selectedWire=-1;show('Conductor desconnectat.');}
 else if(selectedDevice&&state.devices[selectedDevice]){ev.preventDefault();retireDevice(selectedDevice);}
}
if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('[data-device-remove],[data-protect],[data-program],[data-press],[data-shutter],[data-wire-remove],[data-port],[data-manual]')){ev.preventDefault();ev.target.click();}});
// Animació en temps real: actualitza el model i només les zones visuals de les persianes.
let previousTick=performance.now();
setInterval(()=>{
 const now=performance.now(),dt=Math.min(.3,(now-previousTick)/1000);previousTick=now;
 if(!installed(state,'shutter').length||!advanceShutters(state,dt))return;
 if(section==='laboratori'&&tab==='simulacio'){
  const e=evaluate(state);
  for(const d of installed(state,'shutter')){const box=root.querySelector(`[data-shutter-receiver="${d.id}"]`),room=root.querySelector(`[data-room-device="${d.id}"]`),s=e.status[d.id];if(!s)continue;const pct=Math.round(s.position);const shade=room?.querySelector('.room-shutter-blind');if(shade)shade.setAttribute('height',String((174*s.position/100).toFixed(2)));const roomLabel=room?.querySelector('.room-shutter-label');if(roomLabel)roomLabel.textContent=`${pct} % tancada`;if(box){box.querySelector('.shutter-meta strong').textContent=`${pct} % tancada`;box.querySelector('.shutter-meta span').textContent=s.moving?(s.direction==='up'?'↑ Pujant':'↓ Baixant'):'Aturada';}}
 }
 if(section==='laboratori'&&tab==='muntatge'){
  const e=evaluate(state);for(const d of installed(state,'shutter')){const g=root.querySelector(`[data-device="${d.id}"]`);if(g){const s=e.status[d.id];const shade=g.querySelector('.shutter-shade');if(shade)shade.setAttribute('height',String(105*s.position/100));const t=g.querySelector('.shutter-position');if(t)t.textContent=`${Math.round(s.position)} % tancada · ${s.moving?s.direction==='up'?'PUJANT':'BAIXANT':'ATURADA'}`;}}
 }
},200);
document.querySelectorAll('[data-major]').forEach(b=>b.addEventListener('click',()=>{section=b.dataset.major;selectedWire=-1;notice='';render();}));
render();
